CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "AcademicYears" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(9) NOT NULL,
    "StartDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NOT NULL,
    "IsCurrent" boolean NOT NULL,
    CONSTRAINT "PK_AcademicYears" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoles" (
    "Id" text NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_AspNetRoles" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetUsers" (
    "Id" text NOT NULL,
    "FullName" character varying(150) NOT NULL,
    "MustChangePassword" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastLoginAt" timestamp with time zone,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_AspNetUsers" PRIMARY KEY ("Id")
);

CREATE TABLE "AttendanceSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "GraceMinutes" integer NOT NULL,
    "DefaultThreshold" numeric(5,2) NOT NULL,
    "QrExpirySeconds" integer NOT NULL,
    "LocationRequirement" character varying(12) NOT NULL,
    "LateWeight" numeric(3,2) NOT NULL,
    "LateAfterMinutes" integer NOT NULL,
    "OfflineSyncEnabled" boolean NOT NULL,
    "OfflineMaxDelayMinutes" integer NOT NULL,
    "PeriodCount" integer NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AttendanceSettings" PRIMARY KEY ("Id")
);

CREATE TABLE "AuditLogs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Timestamp" timestamp with time zone NOT NULL,
    "ActorId" character varying(450),
    "ActorName" character varying(150) NOT NULL,
    "Action" character varying(60) NOT NULL,
    "EntityType" character varying(60) NOT NULL,
    "EntityId" character varying(80),
    "BranchId" integer,
    "OldValues" text,
    "NewValues" text,
    "Reason" character varying(400),
    "Details" text,
    "IpAddress" character varying(45),
    CONSTRAINT "PK_AuditLogs" PRIMARY KEY ("Id")
);

CREATE TABLE "BackupHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "At" timestamp with time zone NOT NULL,
    "Action" character varying(20) NOT NULL,
    "FileName" character varying(200) NOT NULL,
    "SizeBytes" bigint NOT NULL,
    "Status" character varying(20) NOT NULL,
    "Message" character varying(500),
    "By" character varying(150),
    CONSTRAINT "PK_BackupHistories" PRIMARY KEY ("Id")
);

CREATE TABLE "Branches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Code" character varying(15) NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Branches" PRIMARY KEY ("Id")
);

CREATE TABLE "Holidays" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" timestamp with time zone NOT NULL,
    "Name" character varying(120) NOT NULL,
    "Type" character varying(20) NOT NULL,
    CONSTRAINT "PK_Holidays" PRIMARY KEY ("Id")
);

CREATE TABLE "Notices" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(150) NOT NULL,
    "Body" character varying(2000) NOT NULL,
    "Audience" character varying(20) NOT NULL,
    "BranchId" integer,
    "SectionId" integer,
    "PublishedAt" timestamp with time zone NOT NULL,
    "ExpiresAt" timestamp with time zone,
    "IsPinned" boolean NOT NULL,
    "CreatedBy" character varying(150) NOT NULL,
    CONSTRAINT "PK_Notices" PRIMARY KEY ("Id")
);

CREATE TABLE "PeriodDefinitions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PeriodNo" integer NOT NULL,
    "StartTime" interval NOT NULL,
    "EndTime" interval NOT NULL,
    CONSTRAINT "PK_PeriodDefinitions" PRIMARY KEY ("Id")
);

CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetRoleClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_AspNetUserClaims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId" FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Faculty" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FacultyID" character varying(20) NOT NULL,
    "FullName" character varying(120) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "Phone" character varying(15) NOT NULL,
    "BranchId" integer,
    "Department" character varying(100) NOT NULL,
    "Designation" character varying(60) NOT NULL,
    "IsHOD" boolean NOT NULL,
    "IsActive" boolean NOT NULL,
    "IdentityUserId" character varying(450),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Faculty" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Faculty_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Sections" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(10) NOT NULL,
    "BranchId" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Sections" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Sections_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Subjects" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SubjectName" character varying(150) NOT NULL,
    "SubjectCode" character varying(30) NOT NULL,
    "BranchId" integer NOT NULL,
    "Semester" integer NOT NULL,
    "Credits" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Subjects" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Subjects_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Students" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StudentID" character varying(30) NOT NULL,
    "FullName" character varying(120) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "Phone" character varying(15) NOT NULL,
    "BranchId" integer NOT NULL,
    "SectionId" integer NOT NULL,
    "Semester" integer NOT NULL,
    "Year" integer NOT NULL,
    "PhotoPath" character varying(200),
    "QRPath" character varying(200),
    "IdentityUserId" character varying(450),
    "JoiningDate" timestamp with time zone NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "RowVersion" bytea NOT NULL,
    CONSTRAINT "PK_Students" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Students_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Students_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ThresholdRules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer,
    "Semester" integer,
    "SectionId" integer,
    "Percent" numeric(5,2) NOT NULL,
    "Note" character varying(200),
    CONSTRAINT "PK_ThresholdRules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ThresholdRules_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ThresholdRules_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "FacultySubjectMappings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FacultyId" integer NOT NULL,
    "SubjectId" integer NOT NULL,
    "BranchId" integer NOT NULL,
    "SectionId" integer NOT NULL,
    "Semester" integer NOT NULL,
    "AcademicYearId" integer NOT NULL,
    "Active" boolean NOT NULL,
    CONSTRAINT "PK_FacultySubjectMappings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FacultySubjectMappings_AcademicYears_AcademicYearId" FOREIGN KEY ("AcademicYearId") REFERENCES "AcademicYears" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FacultySubjectMappings_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FacultySubjectMappings_Faculty_FacultyId" FOREIGN KEY ("FacultyId") REFERENCES "Faculty" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FacultySubjectMappings_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FacultySubjectMappings_Subjects_SubjectId" FOREIGN KEY ("SubjectId") REFERENCES "Subjects" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Timetables" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BranchId" integer NOT NULL,
    "SectionId" integer NOT NULL,
    "Semester" integer NOT NULL,
    "Day" integer NOT NULL,
    "Period" integer NOT NULL,
    "SubjectId" integer NOT NULL,
    "FacultyId" integer NOT NULL,
    "RoomNo" character varying(20) NOT NULL,
    "ClassType" character varying(30) NOT NULL,
    "StartTime" interval NOT NULL,
    "EndTime" interval NOT NULL,
    "IsActive" boolean NOT NULL,
    "AcademicYearId" integer NOT NULL,
    CONSTRAINT "PK_Timetables" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Timetables_AcademicYears_AcademicYearId" FOREIGN KEY ("AcademicYearId") REFERENCES "AcademicYears" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Timetables_Branches_BranchId" FOREIGN KEY ("BranchId") REFERENCES "Branches" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Timetables_Faculty_FacultyId" FOREIGN KEY ("FacultyId") REFERENCES "Faculty" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Timetables_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Timetables_Subjects_SubjectId" FOREIGN KEY ("SubjectId") REFERENCES "Subjects" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "AttendanceQueries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StudentId" integer NOT NULL,
    "BranchId" integer NOT NULL,
    "SubjectId" integer NOT NULL,
    "FacultyId" integer,
    "RecordDate" timestamp with time zone NOT NULL,
    "Message" character varying(500) NOT NULL,
    "Status" character varying(15) NOT NULL,
    "Response" character varying(500),
    "ResponderName" character varying(150),
    "CreatedAt" timestamp with time zone NOT NULL,
    "RespondedAt" timestamp with time zone,
    CONSTRAINT "PK_AttendanceQueries" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AttendanceQueries_Students_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AttendanceQueries_Subjects_SubjectId" FOREIGN KEY ("SubjectId") REFERENCES "Subjects" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "AttendanceSessions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TimetableId" integer NOT NULL,
    "AcademicYearId" integer NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Period" integer NOT NULL,
    "SubjectId" integer NOT NULL,
    "SectionId" integer NOT NULL,
    "FacultyId" integer NOT NULL,
    "Mode" character varying(20) NOT NULL,
    "DeviceId" character varying(64),
    "Latitude" numeric(8,3),
    "Longitude" numeric(8,3),
    "StartedByUserId" character varying(450),
    "StartedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_AttendanceSessions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AttendanceSessions_AcademicYears_AcademicYearId" FOREIGN KEY ("AcademicYearId") REFERENCES "AcademicYears" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AttendanceSessions_Faculty_FacultyId" FOREIGN KEY ("FacultyId") REFERENCES "Faculty" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AttendanceSessions_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AttendanceSessions_Subjects_SubjectId" FOREIGN KEY ("SubjectId") REFERENCES "Subjects" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_AttendanceSessions_Timetables_TimetableId" FOREIGN KEY ("TimetableId") REFERENCES "Timetables" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Attendance" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "StudentId" integer NOT NULL,
    "SubjectId" integer NOT NULL,
    "FacultyId" integer NOT NULL,
    "SectionId" integer NOT NULL,
    "BranchId" integer NOT NULL,
    "Semester" integer NOT NULL,
    "Date" timestamp with time zone NOT NULL,
    "Period" integer NOT NULL,
    "Status" character varying(10) NOT NULL,
    "MarkedAt" timestamp with time zone NOT NULL,
    "AttendanceSessionId" integer NOT NULL,
    "Source" character varying(20) NOT NULL,
    "DeviceId" character varying(64),
    "LastModifiedAt" timestamp with time zone,
    "LastModifiedBy" character varying(150),
    "RowVersion" bytea NOT NULL,
    CONSTRAINT "PK_Attendance" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Attendance_AttendanceSessions_AttendanceSessionId" FOREIGN KEY ("AttendanceSessionId") REFERENCES "AttendanceSessions" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Attendance_Faculty_FacultyId" FOREIGN KEY ("FacultyId") REFERENCES "Faculty" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Attendance_Sections_SectionId" FOREIGN KEY ("SectionId") REFERENCES "Sections" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Attendance_Students_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Attendance_Subjects_SubjectId" FOREIGN KEY ("SubjectId") REFERENCES "Subjects" ("Id") ON DELETE RESTRICT
);

